SELECT jsonb_build_object(
  'route', shipment_overview->'route',
  'other_keys', (SELECT array_agg(key) FROM jsonb_each(shipment_overview))
) as full_structure FROM shipments WHERE shipment_overview ? 'route' LIMIT 1;

SELECT COUNT(*) as total_shipments, 
       SUM(CASE WHEN s.shipment_overview->'route'->>'risk_note' = 'High' THEN 1 ELSE 0 END) as high_risk_count
FROM shipments s;
